function sampleTrackValue(track,frame,def){const keys=track?.keys||[];if(!keys.length)return def.slice();if(frame<=keys[0].frame)return keys[0].value.slice();if(frame>=keys.at(-1).frame)return keys.at(-1).value.slice();let a=keys[0],b=keys.at(-1);for(let i=1;i<keys.length;i++)if(frame<=keys[i].frame){a=keys[i-1];b=keys[i];break;}const t=(frame-a.frame)/Math.max(1,b.frame-a.frame);return a.value.map((v,i)=>v+(b.value[i]-v)*t);}
function quatRotate(v,q){let [x,y,z]=v,[qx,qy,qz,qw]=q,n=Math.hypot(qx,qy,qz,qw)||1;qx/=n;qy/=n;qz/=n;qw/=n;const ix=qw*x+qy*z-qz*y,iy=qw*y+qz*x-qx*z,iz=qw*z+qx*y-qy*x,iw=-qx*x-qy*y-qz*z;return[ix*qw+iw*-qx+iy*-qz-iz*-qy,iy*qw+iw*-qy+iz*-qx-ix*-qz,iz*qw+iw*-qz+ix*-qy-iy*-qx];}
function applyNodePoint(p,node,frame){const pivot=node?.pivot||{x:0,y:0,z:0},tr=sampleTrackValue(node?.tracks?.KGTR,frame,[0,0,0]),sc=sampleTrackValue(node?.tracks?.KGSC,frame,[1,1,1]),rt=sampleTrackValue(node?.tracks?.KGRT,frame,[0,0,0,1]);let v=[p.x-pivot.x,p.y-pivot.y,p.z-pivot.z];v=[v[0]*sc[0],v[1]*sc[1],v[2]*sc[2]];v=quatRotate(v,rt);return{x:v[0]+pivot.x+tr[0],y:v[1]+pivot.y+tr[1],z:v[2]+pivot.z+tr[2]};}
function worldPointForBone(model,p,boneId,frame){const byId=new Map((model.nodes||[]).map(n=>[Number(n.id),n])),chain=[];let n=byId.get(Number(boneId)),guard=0;while(n&&guard++<100){chain.push(n);n=byId.get(Number(n.parentId));}let out={...p};for(const node of chain)out=applyNodePoint(out,node,frame);return out;}

