async function assetBrowserSearch(query,type='all',{timeout=45000,required=true}={}){
  const pro=window.WC3_MODEL_LAB_PRO;if(!pro?.isMounted?.())skip('v1.4 Asset Browser is not mounted.');
  window.WC3_WORKSPACE_UI?.openModule?.('casc');await frames(2);const q=$('#proAssetQuery'),t=$('#proAssetType'),btn=$('#proAssetSearch'),box=$('#proAssetResults');assert(q&&t&&btn&&box,'CASC Asset Browser search controls are missing');
  q.value=String(query||'');t.value=type;dispatch(q,'input');dispatch(t,'change');const before=pro.getState?.().assetResults;btn.click();
  await waitFor(()=>!btn.disabled&&pro.getState?.().assetResults!==before,{timeout,message:`Asset Browser search timed out: ${query}`});await frames(2);
  const rows=[...box.querySelectorAll('.pro-asset-row')];if(required)assert(rows.length>0,`Asset Browser returned no ${type} results for: ${query}`);return rows;
}
async function previewSelectedBrowserAsset({timeout=60000,requireModel=true}={}){
  const pro=window.WC3_MODEL_LAB_PRO,btn=$('#proAssetPreview'),canvas=$('#proAssetPreviewCanvas'),info=$('#proAssetPreviewInfo');assert(btn&&canvas,'Asset preview controls are missing');
  const beforeState=pro.getState?.()||{},beforeModel=beforeState.assetPreviewModel,beforeImage=beforeState.assetPreviewImage,beforeHash=canvasHash(canvas),beforeInfo=String(info?.textContent||''),expectedPath=String(beforeState.assetSelected||'');btn.click();
  // A previous negative-path CASC test may intentionally leave "Preview
  // failed:" in the info label. Treat an error as belonging to this preview
  // only when the label changed after the click. Success must belong to the
  // selected path captured before the operation started.
  const sawBusy=btn.disabled;await frames(1);
  await waitFor(()=>{const st=pro.getState?.()||{},completed=!btn.disabled,currentInfo=String(info?.textContent||''),currentFailure=completed&&currentInfo!==beforeInfo&&/^Preview failed:/i.test(currentInfo),changed=completed&&st.assetPreviewPath===expectedPath&&((st.assetPreviewModel&&st.assetPreviewModel!==beforeModel)||(st.assetPreviewImage&&st.assetPreviewImage!==beforeImage));return (sawBusy||completed)&&(currentFailure||changed);},{timeout,message:'Asset preview did not finish'});await frames(2);
  const st=pro.getState?.()||{};assert(!/^Preview failed:/i.test(String(info?.textContent||'')),String(info?.textContent||'Asset preview failed'));assert(st.assetPreviewPath===expectedPath,'Asset preview completed for a different/stale selection',{expectedPath,actualPath:st.assetPreviewPath});const afterHash=canvasHash(canvas);if(requireModel){assert(st.assetPreviewModel,'Selected Warcraft asset did not parse as a model/effect');assert(st.assetPreviewRuntime,'Selected Warcraft model parsed, but full CASC texture/animation runtime was not created',{path:st.assetPreviewPath});}assert(afterHash!=='none'&&afterHash!==beforeHash,'Asset preview canvas did not visibly update',{beforeHash,afterHash,path:st.assetPreviewPath});return{state:st,beforeHash,afterHash};
}
async function findWarcraftEffectAsset(){
  const existing=(API.getModel()?.attachments||[]).find(x=>String(x?.path||'').trim())?.path||'';
  const base=fileBase(existing).replace(/\.(mdx|mdl)$/i,'');const queries=[base,'TalkToMe','Fire'].filter((x,i,a)=>x&&a.indexOf(x)===i);
  for(const query of queries){const rows=await assetBrowserSearch(query,'effects',{required:false});if(rows.length){rows[0].click();await frames(1);return{query,path:window.WC3_MODEL_LAB_PRO?.getState?.().assetSelected||rows[0].querySelector('small')?.textContent||''};}}
  return null;
}

